WITH long_format AS (SELECT * FROM (SELECT id, device_code, temp_c, humidity, pressure FROM device_readings) src UNPIVOT INCLUDE NULLS (value FOR measure IN (temp_c, humidity, pressure)) unp) SELECT CASE WHEN value >= 76 THEN 'LARGE' ELSE 'SMALL' END AS value_tier, COUNT(DISTINCT device_code) AS distinct_device_codes, SORT_ARRAY(COLLECT_SET(device_code)) AS device_code_list, COUNT(*) FILTER (WHERE device_code = 'DV-02') AS dv_02_rows, SIZE(COLLECT_SET(measure)) AS num_measures FROM long_format GROUP BY 1 ORDER BY distinct_device_codes DESC;
